#!/usr/bin/env bash
# Writes third_party/LICENSES.md: the license and patent texts of every
# library in third_party/versions.lock, taken from the pinned sources.
#
# Usage: third_party/build/collect-licenses.sh [--out FILE]
#
# Rerun it whenever versions.lock changes and commit the result. The output is
# deterministic, so CI can check that it is up to date with
#   third_party/build/collect-licenses.sh && git diff --exit-code third_party/LICENSES.md

set -euo pipefail

# shellcheck source=common.sh
source "$(dirname "${BASH_SOURCE[0]}")/common.sh"

OUT="$WT_ROOT/third_party/LICENSES.md"
while [ $# -gt 0 ]; do
  case "$1" in
    --out) OUT="$2"; shift 2 ;;
    -h | --help) sed -n '2,9p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) wt_die "unknown argument '$1' (see --help)" ;;
  esac
done

wt_require curl git shasum tar awk

# license_info <name>: prints "<SPDX id>|<files...>" (paths relative to the
# source root). Only files covering code that ends up in the prebuilts.
license_info() {
  case "$1" in
    # third_party/x86inc is assembled into the x86 builds.
    libvpx) echo "BSD-3-Clause|LICENSE PATENTS third_party/x86inc/LICENSE" ;;
    libwebm) echo "BSD-3-Clause|LICENSE.TXT PATENTS.TXT" ;;
    libyuv) echo "BSD-3-Clause|LICENSE PATENTS" ;;
    libwebp) echo "BSD-3-Clause|COPYING PATENTS" ;;
    giflib) echo "MIT|COPYING" ;;
    # Only lz4's lib/ is built; the CLI is GPL-2.0 and is not.
    lz4) echo "BSD-2-Clause|lib/LICENSE" ;;
    *) wt_die "no license mapping for '$1'; add it to collect-licenses.sh" ;;
  esac
}

# Every lock entry needs a mapping, and every mapping a lock entry.
lock_names="$(awk '$1 !~ /^#/ && NF { print $1 }' "$WT_LOCK" | sort | tr '\n' ' ')"
known_names="$(echo $WT_LIBS | tr ' ' '\n' | sort | tr '\n' ' ')"
[ "$lock_names" = "$known_names" ] ||
  wt_die "versions.lock lists [$lock_names] but the build scripts know [$known_names]"

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

{
  echo "# Third-party licenses"
  echo
  echo "<!-- Generated by third_party/build/collect-licenses.sh from third_party/versions.lock. Do not edit. -->"
  echo
  echo "The native libraries bundled with webm_texture include the following"
  echo "third-party code."
  echo
  echo "| Library | Version | License | Source |"
  echo "|---|---|---|---|"
  for lib in $WT_LIBS; do
    info="$(license_info "$lib")" || exit 1
    version="$(wt_lock_field "$lib" version)" || exit 1
    url="$(wt_lock_field "$lib" url)" || exit 1
    echo "| $lib | \`$version\` | ${info%%|*} | ${url#git+} |"
  done
} >"$tmp"

for lib in $WT_LIBS; do
  wt_fetch_source "$lib"
  info="$(license_info "$lib")" || exit 1
  {
    echo
    echo "## $lib"
    for file in ${info#*|}; do
      [ -f "$WT_FETCHED/$file" ] || wt_die "$lib: license file '$file' not found"
      echo
      echo "### \`$file\`"
      echo
      echo '```text'
      # Strip trailing whitespace and CRLFs so the output is stable.
      sed -e 's/[[:space:]]*$//' "$WT_FETCHED/$file"
      echo '```'
    done
  } >>"$tmp"
done

mkdir -p "$(dirname "$OUT")"
mv "$tmp" "$OUT"
trap - EXIT
wt_log "wrote ${OUT#"$WT_ROOT"/}"
